import React, { useState } from 'react';
import { companyInfo, offerings } from '../mockData';
import AboutContent from './About/AboutContent';
import OfferingsSidebar from './About/OfferingsSidebar';
import ProductModal from './ProductModal';
import { products } from '../mockData';

const AboutSection = () => {
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleOfferingClick = (offeringName) => {
    // Find the matching product
    let product = null;
    if (offeringName === "PP DANLINE ROPES") {
      product = products.find(p => p.category === "PP DANLINE ROPES");
    } else if (offeringName === "HDPE ROPES") {
      product = products.find(p => p.category === "HDPE ROPES");
    }
    
    if (product) {
      setSelectedProduct(product);
      setIsModalOpen(true);
    }
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedProduct(null);
  };

  return (
    <>
      <section className="py-20 bg-white">
        <div className="container mx-auto px-4">
          <h2 className="text-center text-3xl font-light text-gray-600 tracking-[0.2em] mb-16">
            QUALITY WORK SINCE 2012
          </h2>
          
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
            <AboutContent companyInfo={companyInfo} />
            <OfferingsSidebar offerings={offerings} onOfferingClick={handleOfferingClick} />
          </div>
        </div>
      </section>
      
      <ProductModal 
        isOpen={isModalOpen} 
        onClose={closeModal} 
        product={selectedProduct} 
      />
    </>
  );
};

export default AboutSection;
